import io,json,sys,urllib.error
from unittest.mock import patch
sys.path.insert(0,'/workspace')
import openai_client as c
class Fake:
 def open(self,req,timeout):
  assert req.full_url=='https://api.openai.com/v1/responses'
  assert req.get_header('Authorization')=='Bearer test-key'
  assert json.loads(req.data)=={'model':'test-model','input':'test prompt','store':False}
  return io.BytesIO(json.dumps({'status':'completed','output':[{'type':'reasoning'},{'type':'message','content':[{'type':'output_text','text':'Hello'}]}]}).encode())
with patch.object(c.urllib.request,'build_opener',return_value=Fake()):
 assert c.send_prompt('test prompt',model='test-model',api_key='[REDACTED_SECRET]')=='Hello'
with patch.object(c.urllib.request.OpenerDirector,'open',side_effect=urllib.error.HTTPError(c._ENDPOINT,429,'private body',{},io.BytesIO(b'private body'))):
 try: c.send_prompt('test prompt',model='test-model',api_key='[REDACTED_SECRET]')
 except c.OpenAIError as e:
  assert str(e)=='OpenAI request failed (HTTP 429).'
  assert e.__context__ is None
 else: raise AssertionError('HTTP error not raised')
for result in [{'status':'incomplete'}, {'status':'completed','output':[{'type':'message','content':[{'type':'refusal'}]}]}]:
 with patch.object(c,'create_response',return_value=result):
  try: c.send_prompt('test',model='test-model')
  except c.OpenAIError: pass
  else: raise AssertionError('Expected error')
assert c._NoRedirect().redirect_request(None,None,302,'',{},'https://example.com') is None
print('Mock checks passed: request payload, text extraction, sanitized HTTP errors, incomplete responses, refusals, redirect rejection.')
